<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$u=require_user($pdo);$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=$_POST['op']??'create';if($op==='create'){$name=trim($_POST['name']??'');if($name==='')$error='Team name is required.';else{$pdo->beginTransaction();try{$public=ulid_like();$q=$pdo->prepare('INSERT INTO teams(public_id,owner_user_id,name) VALUES(?,?,?)');$q->execute([$public,$u['id'],$name]);$teamId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO team_members(team_id,user_id,role) VALUES(?,?,'owner')")->execute([$teamId,$u['id']]);$pdo->commit();header('Location:/teams.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Unable to create team.';}}}elseif($op==='invite'){$teamPublic=(string)($_POST['team']??'');$username=trim($_POST['username']??'');$q=$pdo->prepare("SELECT t.id FROM teams t JOIN team_members tm ON tm.team_id=t.id WHERE t.public_id=? AND tm.user_id=? AND tm.role IN ('owner','admin')");$q->execute([$teamPublic,$u['id']]);$teamId=(int)($q->fetchColumn()?:0);$q=$pdo->prepare('SELECT id FROM users WHERE username=? AND status="active"');$q->execute([$username]);$memberId=(int)($q->fetchColumn()?:0);if(!$teamId||!$memberId)$error='Team or user not found, or you do not have permission.';else{$pdo->prepare("INSERT IGNORE INTO team_members(team_id,user_id,role) VALUES(?,?,'researcher')")->execute([$teamId,$memberId]);$success='Member added.';}}}
$q=$pdo->prepare('SELECT t.public_id,t.name,tm.role,(SELECT COUNT(*) FROM team_members x WHERE x.team_id=t.id) member_count FROM teams t JOIN team_members tm ON tm.team_id=t.id WHERE tm.user_id=? ORDER BY t.name');$q->execute([$u['id']]);$teams=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teams · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/home.php">Home</a><a href="/research.php">Research</a><a href="/teams.php">Teams</a><a href="/notifications.php">Notifications</a></nav></header><main class="layout"><section><div class="pageTitle"><span class="eyebrow">TEAMS</span><h1>Research together</h1><p>Team membership also controls access to private Team Live rooms in the Chrome sidebar.</p></div><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if(!$teams):?><div class="card empty">No teams yet.</div><?php endif?><?php foreach($teams as $t):?><article class="card"><div class="meta"><?=h(ucfirst($t['role']))?> · <?=h((string)$t['member_count'])?> members</div><h2><?=h($t['name'])?></h2><?php if(in_array($t['role'],['owner','admin'],true)):?><form method="post" class="inlineForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="invite"><input type="hidden" name="team" value="<?=h($t['public_id'])?>"><input name="username" placeholder="Username to add" required><button>Add researcher</button></form><?php endif?></article><?php endforeach?></section><aside><div class="card"><h3>Create team</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="op" value="create"><label>Team name<input name="name" required></label><button>Create team</button></form></div></aside></main></body></html>